// Hand-authored in place of generate_ontology.py output.
//
// This would normally be generated by `python scripts/generate_ontology.py`
// from examples/tictactoe/schema/tictactoe.yaml (see docs/GETTING_STARTED.md
// step 2). That generator needs an unpublished maintainer LinkML C++
// toolchain (docs/GETTING_STARTED.md:85-86), so this file is hand-written
// from the schema instead -- the same technique
// tests/test_ontology_extension.cpp uses for its example farming ontology.
// Keep it in sync with tictactoe.yaml if the schema changes.
#pragma once

#include "logosphere/kg/ontology_registry.h"

namespace tictactoe::ontology {

/// Returns the singleton ontology registry populated from the schema YAML.
/// This is the TBox that defines the KG's type system for this game.
const kg::OntologyRegistry& registry();

} // namespace tictactoe::ontology
